@push('styles')<style>.hero{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.hero h1{font-size:clamp(26px,4vw,40px);margin:6px 0}.eyebrow{font-size:9px;letter-spacing:.14em;color:#4ec5e5}.back{display:inline-flex;align-items:center;gap:7px;padding:10px 13px;border:1px solid var(--line);border-radius:11px;color:#9db9c2;text-decoration:none;font-size:10px}.card{max-width:1100px;padding:20px;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.02)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.full{grid-column:1/-1}label{display:block;color:#89a7b2;font-size:10px;margin-bottom:7px}input,select,textarea{width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:10px;background:#061923;color:#e4f3f7;padding:11px;font:inherit;font-size:11px;outline:none}textarea{resize:vertical;line-height:1.6}.locked-type{height:40px;display:flex;align-items:center;gap:9px;padding:0 12px;border:1px solid var(--line);border-radius:10px;background:rgba(67,194,229,.05);color:#b9e6ef;font-size:11px}.locked-type i{color:#61d5ed}.editor-shell{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#061923}.editor-toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:9px;border-bottom:1px solid var(--line);background:rgba(67,194,229,.04)}.editor-toolbar button{min-width:34px;height:32px;border:1px solid transparent;border-radius:8px;background:transparent;color:#a7c2cb;cursor:pointer}.editor-toolbar button:hover{background:rgba(67,194,229,.12);color:#eaf8fb}.editor{min-height:430px;padding:18px;color:#e6f4f7;line-height:1.75;font-size:13px;outline:none}.editor img,.editor video{max-width:100%;height:auto;border-radius:12px;margin:10px 0}.editor iframe{max-width:100%;width:100%;min-height:360px;border:0;border-radius:12px;margin:10px 0;background:#000}.media-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:14px 0}.media-gallery img{width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:10px}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.save{border:0;border-radius:11px;padding:12px 16px;background:#29aaca;color:#fff;font-weight:700}.errors{padding:11px;border-radius:10px;margin-bottom:14px;background:rgba(210,65,65,.12);color:#ffb0b0}@media(max-width:650px){.hero{align-items:flex-start;gap:12px;flex-direction:column}.grid{grid-template-columns:1fr}.full{grid-column:auto}.editor{min-height:360px}.editor-toolbar{position:sticky;top:0;z-index:2}.actions>*{flex:1;text-align:center}.media-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>@endpush
