@push('scripts')<script>const editor=document.getElementById('editor'),source=document.getElementById('content-source'),form=document.getElementById('content-form'),mediaInput=document.getElementById('media-input'),galleryInput=document.getElementById('gallery-input'),videoInput=document.getElementById('video-input');function sync(){source.value=editor.innerHTML}function exec(cmd,value=null){editor.focus();document.execCommand(cmd,false,value);sync()}document.querySelectorAll('.editor-toolbar [data-cmd]').forEach(b=>b.addEventListener('click',()=>exec(b.dataset.cmd,b.dataset.value||null)));document.getElementById('insert-link').onclick=()=>{const url=prompt('URL');if(url)exec('createLink',url)};async function upload(file){const fd=new FormData();fd.append('media',file);const res=await fetch('{{ route('admin.site-content.media') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:fd});if(!res.ok)throw new Error('Upload failed');return res.json()}document.getElementById('upload-image').onclick=()=>mediaInput.click();mediaInput.onchange=async()=>{if(!mediaInput.files[0])return;try{const d=await upload(mediaInput.files[0]);exec('insertHTML',`<img src="${d.url}" alt="${d.name.replaceAll('"','')}" loading="lazy">`)}catch(e){alert(e.message)}mediaInput.value=''};document.getElementById('upload-video').onclick=()=>videoInput.click();videoInput.onchange=async()=>{if(!videoInput.files[0])return;try{const d=await upload(videoInput.files[0]);exec('insertHTML',`<video controls preload="metadata" src="${d.url}"></video>`)}catch(e){alert(e.message)}videoInput.value=''};document.getElementById('insert-youtube').onclick=()=>{const url=prompt('YouTube URL');if(!url)return;const m=url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|shorts\/|embed\/))([^?&/]+)/);if(m)exec('insertHTML',`<iframe src="https://www.youtube.com/embed/${m[1]}" title="YouTube" allowfullscreen loading="lazy"></iframe>`)};document.getElementById('insert-facebook').onclick=()=>{const url=prompt('Facebook video URL');if(url)exec('insertHTML',`<iframe src="https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(url)}&show_text=false" title="Facebook" allowfullscreen loading="lazy"></iframe>`)};document.getElementById('insert-gallery').onclick=()=>galleryInput.click();galleryInput.onchange=async()=>{const files=[...galleryInput.files];if(!files.length)return;try{const uploads=[];for(const file of files)uploads.push(await upload(file));exec('insertHTML','<div class="media-gallery">'+uploads.map(d=>`<img src="${d.url}" alt="${d.name.replaceAll('"','')}" loading="lazy">`).join('')+'</div>')}catch(e){alert(e.message)}galleryInput.value=''};form.addEventListener('submit',sync);editor.addEventListener('input',sync);sync();</script>@endpush
